import math
import numpy as np
import pandas as pd
from .models import Candle
def technical_snapshot(candles:list[Candle])->dict:
 if len(candles)<30:raise ValueError("At least 30 candles are required")
 f=pd.DataFrame([{"close":x.close,"high":x.high,"low":x.low,"volume":x.volume} for x in candles]);close=f.close;delta=close.diff();gain=delta.clip(lower=0).ewm(alpha=1/14,adjust=False).mean();loss=(-delta.clip(upper=0)).ewm(alpha=1/14,adjust=False).mean();rsi=100-(100/(1+gain/loss));prev=close.shift(1);tr=pd.concat([f.high-f.low,(f.high-prev).abs(),(f.low-prev).abs()],axis=1).max(axis=1);atr=tr.ewm(alpha=1/14,adjust=False).mean();returns=close.pct_change();vol=returns.tail(20).std()*math.sqrt(252)*100;rv=f.volume.iloc[-1]/f.volume.tail(20).mean() if f.volume.tail(20).mean() else None;sma20=close.tail(20).mean();sma50=close.tail(50).mean() if len(close)>=50 else None;trend=(50 if close.iloc[-1]>sma20 else -50)+(50 if sma50 is not None and close.iloc[-1]>sma50 else -50 if sma50 is not None else 0);momentum=(close.iloc[-1]/close.iloc[-21]-1)*100
 ema12=close.ewm(span=12,adjust=False).mean();ema26=close.ewm(span=26,adjust=False).mean();macd=ema12-ema26;signal=macd.ewm(span=9,adjust=False).mean();std20=close.rolling(20).std();low14=f.low.rolling(14).min();high14=f.high.rolling(14).max();stoch=(close-low14)/(high14-low14)*100;typical=(f.high+f.low+close)/3;vwap=(typical*f.volume).cumsum()/f.volume.cumsum().replace(0,np.nan);up=f.high.diff();down=-f.low.diff();plus=up.where((up>down)&(up>0),0.);minus=down.where((down>up)&(down>0),0.);plus_di=100*plus.ewm(alpha=1/14,adjust=False).mean()/atr;minus_di=100*minus.ewm(alpha=1/14,adjust=False).mean()/atr;adx=(100*(plus_di-minus_di).abs()/(plus_di+minus_di).replace(0,np.nan)).ewm(alpha=1/14,adjust=False).mean()
 return {"close":float(close.iloc[-1]),"rsi":round(float(rsi.iloc[-1]),2),"atr":round(float(atr.iloc[-1]),4),"atr_pct":round(float(atr.iloc[-1]/close.iloc[-1]*100),2),"volatility":round(float(vol),2),"relative_volume":round(float(rv),2) if rv is not None else None,"momentum_20d":round(float(momentum),2),"trend_score":trend,"sma20":round(float(sma20),4),"sma50":round(float(sma50),4) if sma50 is not None else None,"ema12":round(float(ema12.iloc[-1]),4),"ema26":round(float(ema26.iloc[-1]),4),"macd":round(float(macd.iloc[-1]),4),"macd_signal":round(float(signal.iloc[-1]),4),"bollinger_upper":round(float((sma20+2*std20.iloc[-1])),4),"bollinger_lower":round(float((sma20-2*std20.iloc[-1])),4),"stochastic":round(float(stoch.iloc[-1]),2),"vwap":round(float(vwap.iloc[-1]),4) if pd.notna(vwap.iloc[-1]) else None,"adx":round(float(adx.iloc[-1]),2) if pd.notna(adx.iloc[-1]) else None}
def portfolio_risk(price_series,weights,benchmark=None):
 frames={k:pd.Series(v).pct_change().dropna().reset_index(drop=True) for k,v in price_series.items() if len(v)>=20}
 if not frames:return {"complete":False,"reason":"insufficient_history"}
 returns=pd.DataFrame(frames).dropna();ordered=[k for k in returns.columns if k in weights];w=np.array([weights[k] for k in ordered]);w=w/w.sum() if w.sum() else w;port=returns[ordered].dot(w);curve=(1+port).cumprod();dd=curve/curve.cummax()-1;variance=port.var();sharpe=port.mean()/math.sqrt(variance)*math.sqrt(252) if variance else 0;corr=returns[ordered].corr().round(3).to_dict();beta=None
 if benchmark and len(benchmark)>=len(port)+1:
  b=pd.Series(benchmark).pct_change().dropna().tail(len(port)).reset_index(drop=True);beta=float(np.cov(port,b)[0,1]/b.var()) if b.var() else None
 return {"complete":True,"annualized_volatility_pct":round(float(port.std()*math.sqrt(252)*100),2),"max_drawdown_pct":round(float(dd.min()*100),2),"historical_var_95_pct":round(float(np.quantile(port,.05)*100),2),"sharpe":round(float(sharpe),2),"beta":round(beta,2) if beta is not None else None,"correlation":corr,"observations":len(port)}
